import sailpoint.object.Identity;
import sailpoint.object.Link;
import sailpoint.api.SailPointContext;
import sailpoint.api.IdentityService;

import org.apache.log4j.Logger;

Logger log = Logger.getLogger("iiq.alpha.Alpha-Rule-ActiveDirectory-ProvisionPolicy-Mail-Calculation-Rule");
  log.debug("Alpha-Rule-ActiveDirectory-ProvisionPolicy-Mail-Calculation-Rule - STARTS");

boolean createPrivilegeAccount = false;

//Get createPrivilegeAccount property from context which is set in Account Selector rule for privilege account creation

if(null != context.getProperty("createPrivilegeAccount"))
{
  createPrivilegeAccount = Boolean.parseBoolean(context.getProperty("createPrivilegeAccount"));
  log.debug("createPrivilegeAccount"+createPrivilegeAccount );
}

//Check createPrivilegeAccount is true and return mail which is present in primaryAccount

if(createPrivilegeAccount)
{
    IdentityService identityserv = new IdentityService(context);

    List appLinks = identityserv.getLinks(identity, application);

    if(appLinks != null @and appLinks.size() > 0)
    {
      for(Link link :appLinks)
      {
        String link_accountType = link.getAttribute("extensionName");
        if(link_accountType.equals("primaryAccount"))
        {
             String link_Mail = link.getAttribute("mail");
             return link_Mail;
        }
      }
    }
}
log.debug("Alpha-Rule-ActiveDirectory-ProvisionPolicy-Mail-Calculation-Rule - ENDS");
return userPrincipalName;
